using Azure.Identity;
using Azure.Security.KeyVault.Secrets;

var credential = new DefaultAzureCredential();
var client = new SecretClient(new Uri("https://myvault.vault.azure.net/"), credential);

// Set a secret
await client.SetSecretAsync("DbPassword", "SuperSecret123!");
Console.WriteLine("Secret stored.");

// Get a secret
KeyVaultSecret secret = await client.GetSecretAsync("DbPassword");
Console.WriteLine($"Value: {secret.Value}");

// List all secrets
await foreach (SecretProperties item in client.GetPropertiesOfSecretsAsync())
{
    Console.WriteLine(item.Name);
}
